/**
 * Provider-Specific Prompt Adapters
 *
 * Wraps the base system prompt with per-provider adjustments.
 * Different models need different guidance to reliably produce valid JSON.
 */

import { PROVIDERS, type ProviderId } from './providers';

/**
 * Wrap the base system prompt with provider-specific instructions.
 * The base prompt is generated by `generateSystemPrompt()` from catalog.ts.
 * Pass modelId for providers where prompt varies by model capability (e.g., transformers).
 */
export function adaptPromptForProvider(
  baseSystemPrompt: string,
  providerId: ProviderId,
  _modelId?: string,
): string {
  switch (providerId) {
    case 'openai':
    case 'grok':
      return adaptForOpenAI(baseSystemPrompt);
    case 'gemini':
      return adaptForGemini(baseSystemPrompt);
    case 'openrouter':
      return adaptForOpenRouter(baseSystemPrompt);
    case 'ollama':
      return adaptForSmallModels(baseSystemPrompt);
    case 'anthropic':
    default:
      return baseSystemPrompt;
  }
}

// ============================================================================
// Provider-Specific Adapters
// ============================================================================

function adaptForOpenAI(basePrompt: string): string {
  // OpenAI models respond well to explicit JSON mode instructions
  return `${basePrompt}

CRITICAL: You MUST respond with ONLY valid JSON. No markdown, no explanation, no code fences. Just the raw JSON object starting with { and ending with }.`;
}

function adaptForGemini(basePrompt: string): string {
  // Gemini sometimes wraps JSON in markdown fences or adds preamble
  return `${basePrompt}

IMPORTANT: Respond with ONLY a JSON object. Do NOT wrap it in markdown code fences (\`\`\`). Do NOT add any text before or after the JSON. The response must start with { and end with }.`;
}

function adaptForOpenRouter(basePrompt: string): string {
  // OpenRouter routes to many different models, use a universal strong instruction
  return `${basePrompt}

CRITICAL: Your entire response must be a single valid JSON object. No markdown, no code fences, no explanation text. Start with { and end with }. If you cannot fulfill the request, respond with: {"title":"Error","components":[{"type":"TextBlock","content":"I could not process that request.","variant":"warning"}]}`;
}

function adaptForSmallModels(basePrompt: string): string {
  // For Ollama with smaller models — simplify the schema drastically
  return `You are a compliance AI assistant. Respond with a JSON object.

Available component types (use only these):
- TextBlock: {"type":"TextBlock","content":"markdown text here","variant":"default"}
- StatCard: {"type":"StatCard","title":"metric name","value":"number or text"}
- Section: {"type":"Section","title":"heading","children":[...components]}

Response format:
{"title":"Brief title","components":[...array of components above]}

RULES:
- Respond with ONLY valid JSON
- Use only TextBlock, StatCard, and Section components
- Keep responses concise (3-5 components max)
- Use Markdown in TextBlock content for formatting`;
}

/**
 * Simplified system prompt for Transformers.js (very small models).
 * These models can't reliably generate structured JSON for 20+ component types,
 * so we ask for plain text and wrap it client-side.
 */
export const TRANSFORMERS_SYSTEM_PROMPT = `You are a compliance and security frameworks assistant. Answer questions about security controls, regulatory requirements, and compliance frameworks concisely. Use markdown formatting (headers, lists, bold) for readability. Be factual and specific.`;
